import {Assets} from './assets.js';
import {Renderer} from './render.js';
import {World} from './engine.js';
import {GameAudio} from './audio.js';
import {TICK_HZ,Demo,inputFromMask,parsePassword,passwordFor} from './compat.js';
const $=s=>document.querySelector(s),canvas=$('#game'),dialog=$('#dialog');
const audio=new GameAudio();let assets,renderer,world,state='loading',previous='title',muted=true,held={},last=0,acc=0,saveClock=0,demo,toastTimer;
const tracks=['MINES','MINES','PRES','PRES','PRES','MONSTER','GLACE','GLACE','MYSTERY','MONSTER','KOOL','KOOL','KOOL','MINES','FINAL','GLACE'];
const STORAGE='prehistorik2-reconstruction-v1';
let saved;try{saved=JSON.parse(localStorage.getItem(STORAGE));}catch{}
const completed=new Set(saved?.completed||[]);
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2300);}
function sound(p){p?.catch?.(()=>{});}
async function gesture(){try{await audio.unlock();audio.setMuted(muted);}catch{toast('Sound unavailable in this browser');}}
function panel(html,cls=''){held={};dialog.className='screen-dialog '+cls;dialog.innerHTML=html;dialog.hidden=false;}
function button(label,fn,kind='primary'){const b=document.createElement('button');b.className=kind;b.textContent=label;b.onclick=()=>{gesture();fn();};return b;}
function card(kicker,title,body,actions){panel(`<div class="dialog-card"><small>${kicker}</small><h2>${title}</h2>${body}<div class="actions"></div></div>`);for(const [label,fn,kind] of actions)dialog.querySelector('.actions').append(button(label,fn,kind));}
function hide(){dialog.hidden=true;canvas.focus({preventScroll:true});}
function title(){state='title';world=null;renderer.renderScreen('MENU');$('#stage-label').textContent='READY FOR ADVENTURE';$('#status-label').textContent='ORIGINAL WORLDS · ORIGINAL MISCHIEF';sound(audio.setTrack('PRESENTA'));panel('<div class="title-panel"><div class="actions"></div></div>','title');const a=dialog.querySelector('.actions');if(saved)a.append(button('Continue',resume));a.append(button('Start adventure',difficulty));a.append(button('Password',password,'secondary'));}
function difficulty(){state='menu';card('CHOOSE YOUR ADVENTURE','How hungry are you?','<p>Explore the original worlds, uncover hidden food and find the exit key.</p>',[['Beginner',()=>start(0,false)],['Expert',()=>start(0,true),'secondary'],['Back',title,'secondary']]);}
function event(e){if(e.type==='level'){sound(audio.setTrack(tracks[e.index]));$('#stage-label').textContent=`STAGE ${e.id} · ${world?.expert?'EXPERT':'BEGINNER'}`;$('#status-label').textContent='FIND THE KEY · UNCOVER THE FEAST';}
 if(e.type==='sfx')sound(audio.sfx(e.index));if(e.type==='exitOpen')toast('The exit is open!');if(e.type==='weapon')toast('New weapon!');if(e.type==='bossDefeated')toast('Boss defeated — find the exit!');if(e.type==='lifeLost')toast('One more try…');
 if(e.type==='complete'){completed.add(world.level.id);save();}
 if(e.type==='transitionReady'&&state==='play'){state='result';const t=e.transition;save();if(t.type==='complete')card('A PREHISTORIC FEAST','Stage complete',`<p>${t.percent}% collected · Score ${(world.score*10).toLocaleString()}</p><p>Next: stage ${assets.game.levels[t.next]?.id||'finale'}<br>Browser password: <b>${passwordFor(Math.min(t.next,9),world.expert)}</b></p>`,[['Keep going',()=>{world.advance();state='play';hide();save();}],['World map',stages,'secondary']]);else if(t.type==='ending'){renderer.renderScreen('THEEND');card('THE ADVENTURE IS COMPLETE','A feast well earned.',`<p>Final score ${(world.score*10).toLocaleString()}<br>Explore the remaining secret stages from the world map.</p>`,[['Explore stages',stages],['Title screen',title,'secondary']]);}else{sound(audio.setTrack('GAMEOVER'));card('THE STONE AGE IS TOUGH','Game over',`<p>Score ${(world.score*10).toLocaleString()}</p>`,[['Try again',()=>start(world.levelIndex,world.expert)],['Title screen',title,'secondary']]);}}
}
function start(index=0,expert=false){state='play';world=new World(assets,{expert,onEvent:event});if(index)world.loadLevel(index);$('#stage-label').textContent=`STAGE ${world.level.id} · ${expert?'EXPERT':'BEGINNER'}`;hide();save();}
function save(){if(!world||state==='demo')return;const w=world;saved={version:1,level:w.levelIndex,expert:w.expert,score:w.score,lives:w.lives,persistence:w.capturePersistence(),completed:[...completed]};try{localStorage.setItem(STORAGE,JSON.stringify(saved));}catch{}}
function resume(){const s=saved;start(s.level,s.expert);world.score=s.score;world.lives=s.lives;world.restorePersistence(s.persistence);Object.assign(world.player,world.checkpoint,{vx:0,vy:0,invulnerable:24});world.camera.x=Math.max(0,Math.min(world.maxCameraX(),world.player.x-144));world.camera.y=Math.max(0,Math.min(world.maxCameraY(),world.player.y-128));save();toast('Resumed at your checkpoint');}
function pause(){if(state==='play'||state==='demo'){previous=state;state='pause';save();card('TAKE A BREATHER','Adventure paused','<p>Your stage and checkpoint are saved in this browser.</p>',[['Keep playing',()=>{state=previous;hide();}],['Restart stage',()=>{world.loadLevel(world.levelIndex,{restart:true});state='play';hide();}],['World map',stages,'secondary'],['Title screen',title,'secondary']]);}else if(state==='pause'){state=previous;hide();}}
function help(){const back=state,priorHTML=dialog.innerHTML,priorClass=dialog.className,wasHidden=dialog.hidden;state='help';card('KNOW YOUR MOVES','Ready, caveman?','<div class="help-grid"><span><kbd>← →</kbd> Move</span><span><kbd>↑ / Z</kbd> Hold to jump</span><span><kbd>SPACE</kbd> Swing / throw</span><span><kbd>↓</kbd> Crouch / passage</span><span><kbd>X</kbd> Look ahead</span><span><kbd>P</kbd> Pause</span></div><p>Collect food for points and health. Strike hidden blocks to reveal treasure. Pick up the key to open exits. Hold down at passages to travel.</p><p class="fine">A native browser reconstruction using recovered original assets. Some enemy and boss behavior remains approximate.</p>',[['Got it',()=>{state=back;if(back==='title')title();else if(back==='play'||back==='demo')hide();else if(back==='pause'){state='play';pause();}else if(back==='stages')stages();else if(back==='password')password();else if(back==='menu')difficulty();else{dialog.innerHTML=priorHTML;dialog.className=priorClass;dialog.hidden=wasHidden;state='play';pause();}}]]);}
function stages(){const back=world?'play':'title';state='stages';renderer.renderMap(world?.levelIndex||0,16);card('THE ORIGINAL WORLDS','Choose your next adventure','<p>Campaign stages 1–9 and A, plus six secret worlds. Stage selection starts a fresh practice run.</p><div class="stage-grid"></div>',[['Back',()=>{if(world){state=back;hide();}else title();},'secondary']]);dialog.querySelector('.dialog-card').classList.add('stages');const grid=dialog.querySelector('.stage-grid');assets.game.levels.forEach((l,i)=>{const b=button(l.id,()=>start(i,world?.expert||false),'stage-button'+(world?.levelIndex===i?' current':'')+(completed.has(l.id)?' completed':''));b.setAttribute('aria-label',`Play stage ${l.id}`);grid.append(b);});}
function password(){state='password';card('RETURN TO THE ADVENTURE','Enter your password','<p>Use a four-character password from this browser edition.</p><input class="password-input" aria-label="Password" maxlength="4" autocomplete="off" spellcheck="false"><p class="error" role="alert"></p><p class="fine">Original DOS passwords depend on the computer’s ROM profile. This edition uses a fixed portable profile.</p>',[['Continue',()=>{const p=parsePassword(dialog.querySelector('input').value.trim());if(p)start(p.level,p.expert);else dialog.querySelector('.error').textContent='That password is not recognized.';}],['Back',title,'secondary']]);dialog.querySelector('input').focus();}
function toggleSound(){muted=!muted;gesture();audio.setMuted(muted);$('#sound-label').textContent=muted?'Sound off':'Sound on';$('#mute-button').setAttribute('aria-label',muted?'Enable sound':'Mute sound');$('#sound-wave').setAttribute('d',muted?'m16 9 5 6m0-6-5 6':'M15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14');}
$('#mute-button').onclick=toggleSound;$('#pause-button').onclick=pause;$('#help-button').onclick=help;$('#stages-button').onclick=stages;$('#fullscreen-button').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else $('#screen-wrap').requestFullscreen?.().catch(()=>toast('Fullscreen unavailable'));};
const keys={ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',ArrowUp:'up',KeyW:'up',KeyZ:'up',ArrowDown:'down',KeyS:'down',Space:'attack',KeyX:'look'};
window.addEventListener('keydown',e=>{if(e.target.tagName==='INPUT'){if(e.code==='Enter'){e.preventDefault();dialog.querySelector('.primary')?.click();}return;}if(keys[e.code]){e.preventDefault();held[keys[e.code]]=true;gesture();}if(e.repeat)return;if(e.code==='KeyP'||e.code==='Escape'){e.preventDefault();pause();}if(e.code==='KeyM'||e.code==='F3'){e.preventDefault();toggleSound();}if(e.code==='KeyF')$('#fullscreen-button').click();if(e.code==='Enter'&&state!=='play'){e.preventDefault();dialog.querySelector('.primary')?.click();}});
window.addEventListener('keyup',e=>{if(keys[e.code])held[keys[e.code]]=false;});window.addEventListener('blur',()=>{held={};if(state==='play')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){held={};if(state==='play')pause();}});
for(const b of document.querySelectorAll('[data-control]')){const release=()=>{held[b.dataset.control]=false;b.classList.remove('held');};b.onpointerdown=e=>{e.preventDefault();gesture();b.setPointerCapture(e.pointerId);held[b.dataset.control]=true;b.classList.add('held');};b.onpointerup=release;b.onpointercancel=release;b.onlostpointercapture=release;}
function frame(now){const dt=last?Math.min(.25,(now-last)/1000):0;last=now;if(state==='play'||state==='demo'){acc+=dt;while(acc>=1/TICK_HZ){acc-=1/TICK_HZ;world.step(state==='demo'?inputFromMask(demo.next()):held);if(state!=='play'&&state!=='demo')break;}if(state==='play'||state==='demo')renderer.render(world);if((saveClock+=dt)>5){saveClock=0;save();}}else acc=0;requestAnimationFrame(frame);}
try{assets=await Assets.load(p=>$('#loading-progress').style.width=`${p*100}%`);assets.rules=await(await fetch('rules.json')).json();renderer=new Renderer(canvas,assets);$('#loading').hidden=true;title();requestAnimationFrame(frame);if(new URLSearchParams(location.search).has('qa'))window.prehistorik={get world(){return world;},get assets(){return assets;},get renderer(){return renderer;},get state(){return state;},start,pause,step:(n,input={})=>{for(let i=0;i<n;i++)world.step(input);renderer.render(world);return world.snapshot();}};}catch(e){$('#loading-label').textContent='Could not load the adventure. Refresh to try again.';console.error(e);}
